import {freshBattle,loadBattle,saveBattle,planState,forecast,water,movePath,SIZE,clone} from './battle.js';
import {TEXT,translate} from './i18n.js';
import {createBattleScene} from './scene.js';
const $=id=>document.getElementById(id);let storage;try{storage=localStorage;}catch{storage={getItem(){return null},setItem(){throw Error()}};}
let language;try{language=storage.getItem('narai-language')==='th'?'th':'en';}catch{language='en';}
let state=loadBattle(storage),crew={...state.crew},commands=[],mode='move',aim='hull',shown=state,prediction=null,scene,toastTimer,dialogKind=null,saving=true;
const t=(key,params={})=>translate(language,key,params);const name=id=>t(id);const validCrew=()=>Object.values(crew).reduce((a,b)=>a+b,0)===3;
function toast(key){$('toast').textContent=t(key);$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4000);}
function labelCommand(c){if(c.type==='move')return t('planMove',{x:c.x+1,z:c.z+1});if(c.type==='fire')return t('planFire',{unit:name(c.target),aim:t(c.aim)});if(c.type==='turn')return t('planTurn',{direction:t(c.facing)});if(c.type==='signal')return t('planSignal',{route:t(c.route)});return t(c.type==='repair'?'repairAction':c.type);}
function labelEvent(e){return t(e.key,{...e,unit:name(e.unit),target:name(e.target),direction:t(e.direction),route:t(e.route)});}
function add(c){try{planState(state,[...commands,c],crew);commands.push(c);mode='move';render();}catch(e){toast(TEXT[e.message]?e.message:'unknownCommand');}}
function button(text,callback,disabled=false){const b=document.createElement('button');b.textContent=text;b.onclick=callback;b.disabled=disabled;return b;}
function selectOption(title,items,value,onchange){const label=document.createElement('label');label.textContent=t(title);const select=document.createElement('select');for(const [id,text]of items){const o=document.createElement('option');o.value=id;o.textContent=text;select.append(o);}select.value=value;select.onchange=()=>onchange(select.value);label.append(select);$('options').append(label);return select;}
function render(){document.documentElement.lang=language;document.title=t('title');$('language').value=language;document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));document.querySelector('aside').setAttribute('aria-label',t('controls'));$('stage').setAttribute('aria-label',t('board'));$('close-dialog').setAttribute('aria-label',t('close'));$('round').textContent=t('round',{n:state.round});$('stores').textContent=t('supplies',{ammo:state.ammo,timber:state.timber});$('save-status').textContent=t(saving?'saved':'saveFailed');$('unassigned').textContent=t('available',{n:3-Object.values(crew).reduce((a,b)=>a+b,0)});$('order-count').textContent=t('commands',{n:commands.length});$('crew').replaceChildren();
for(const station of['helm','guns','repair']){const row=document.createElement('div');row.className='crew-row';const title=document.createElement('span');title.textContent=t(station);const controls=document.createElement('div');for(const delta of[-1,1]){const b=button(delta<0?'−':'+',()=>{crew[station]+=delta;commands=[];render();},state.status!=='playing'||(delta<0?crew[station]===0:Object.values(crew).reduce((a,b)=>a+b,0)>=3));b.setAttribute('aria-label',t(delta<0?'decrease':'increase',{station:t(station)}));if(delta===1){const n=document.createElement('b');n.textContent=crew[station];controls.append(n);}controls.append(b);}row.append(title,controls);$('crew').append(row);}
try{prediction=state.status==='playing'&&validCrew()?forecast(state,commands,crew):null;shown=prediction?.planned||state;}catch{prediction=null;shown=state;}
const disabled=state.status!=='playing'||!validCrew()||commands.length>=2;$('actions').replaceChildren();for(const key of['move','fire','turn','repairAction','guard','anchor','signal','parley']){const action=key==='repairAction'?'repair':key;const b=button(t(key),()=>{if(['move','fire','turn','signal'].includes(action)){mode=action;render();}else add({type:action});},disabled);b.classList.toggle('selected',mode===action);$('actions').append(b);}
$('options').replaceChildren();if(!disabled&&mode==='move'){const destinations=[];for(let z=0;z<SIZE.h;z++)for(let x=1;x<SIZE.w-1;x++)if(movePath(shown,{x,z})?.length)destinations.push([`${x},${z}`,t('tile',{x:x+1,z:z+1})]);if(destinations.length){let selected=destinations[0][0];selectOption('destinations',destinations,selected,v=>selected=v);$('options').append(button(t('move'),()=>{const[x,z]=selected.split(',').map(Number);add({type:'move',x,z});}));}}
if(!disabled&&mode==='fire'){selectOption('aim',['hull','rigging'].map(v=>[v,t(v)]),aim,v=>{aim=v;});const targets=shown.enemies.filter(e=>e.hp>0);let target=targets[0]?.id;selectOption('target',targets.map(e=>[e.id,name(e.id)]),target,v=>target=v);$('options').append(button(t('fire'),()=>add({type:'fire',target,aim})));}
if(!disabled&&mode==='turn')for(const facing of['north','east','south','west'])$('options').append(button(t(facing),()=>add({type:'turn',facing})));
if(!disabled&&mode==='signal')for(const route of['main','safe','hold'])$('options').append(button(t(route),()=>add({type:'signal',route})));
$('hint').textContent=t(!validCrew()?'crewInvalid':commands.length>=2?'readyHint':mode==='move'?'moveHint':mode==='fire'?'fireHint':'readyHint');$('plan').replaceChildren();if(!commands.length){const item=document.createElement('li');item.textContent=t('noOrders');$('plan').append(item);}else for(const c of commands){const li=document.createElement('li');li.textContent=labelCommand(c);$('plan').append(li);}$('undo').disabled=!commands.length;$('commit').disabled=!prediction;$('commit').textContent=t(commands.length?'commit':'pass');$('forecast-events').replaceChildren();for(const e of prediction?.events||state.log){const li=document.createElement('li');li.textContent=labelEvent(e);$('forecast-events').append(li);}$('health-forecast').textContent=t('healthForecast',{escort:prediction?.next.escort.hp??state.escort.hp,passenger:prediction?.next.passenger.hp??state.passenger.hp});
$('ship-labels').replaceChildren();for(const u of[shown.escort,shown.passenger,...shown.enemies]){if(u.hp<=0)continue;const label=document.createElement('div');label.className='ship-label '+(u.id.startsWith('raider')?'enemy':u.id);label.dataset.unit=u.id;label.textContent=name(u.id)+' · '+u.hp;$('ship-labels').append(label);}if(scene)scene.draw(shown,prediction?.next||state,$('preview').checked,disabled?'':mode);positionLabels();if(dialogKind&&$('dialog').open)dialogContent(dialogKind);}
function positionLabels(){if(!scene)return;for(const label of $('ship-labels').children){const u=[shown.escort,shown.passenger,...shown.enemies].find(v=>v.id===label.dataset.unit);const p=scene.project(u);label.style.left=p.x+'px';label.style.top=p.y+'px';}}
function dialogContent(kind){const root=$('dialog-content');root.replaceChildren();const title=document.createElement('h2');title.textContent=t(kind==='result'?(state.status==='won'?'victory':'defeat'):kind==='restart'?'retry':kind==='inspect'?'inspect':'mission');root.append(title);const p=text=>{const el=document.createElement('p');el.textContent=text;root.append(el);};if(kind==='briefing'){p(t('briefingText'));for(let i=1;i<=5;i++)p(t('rule'+i));p(t('keyboard'));}else if(kind==='inspect'){for(const u of[state.escort,state.passenger,...state.enemies]){const row=document.createElement('div');row.className='unit-row';row.textContent=name(u.id)+' — '+t('hp',{n:u.hp})+' · '+t(u.facing);root.append(row);}}else if(kind==='restart'){p(t('retryConfirm'));root.append(button(t('retry'),()=>{state=freshBattle();crew={...state.crew};commands=[];saving=saveBattle(storage,state);closeDialog();render();}),button(t('cancel'),closeDialog));}else if(kind==='result'){p(t(state.status==='won'?'victoryText':'defeatText'));root.append(button(t('retry'),()=>showDialog('restart')));} }
function showDialog(kind){dialogKind=kind;dialogContent(kind);if(!$('dialog').open)$('dialog').showModal();}
function closeDialog(){$('dialog').close();dialogKind=null;}
$('language').onchange=e=>{language=e.target.value;try{storage.setItem('narai-language',language);}catch{}render();};$('undo').onclick=()=>{commands.pop();render();};$('preview').onchange=render;$('commit').onclick=()=>{if(!prediction)return;state=clone(prediction.next);commands=[];crew={...state.crew};saving=saveBattle(storage,state);render();if(state.status!=='playing')showDialog('result');};$('briefing').onclick=()=>showDialog('briefing');$('inspect').onclick=()=>showDialog('inspect');$('restart').onclick=()=>showDialog('restart');$('close-dialog').onclick=closeDialog;$('dialog').addEventListener('close',()=>dialogKind=null);
try{scene=createBattleScene($('stage'),({x,z})=>{if($('dialog').open||state.status!=='playing'||!validCrew())return;if(mode==='move')add({type:'move',x,z});else if(mode==='fire'){const enemy=shown.enemies.find(e=>e.x===x&&e.z===z&&e.hp>0);if(enemy)add({type:'fire',target:enemy.id,aim});else toast('badArc');}});}catch(error){$('webgl-error').hidden=false;$('webgl-error').textContent=t('noWebGL');console.error(error);}
new ResizeObserver(positionLabels).observe($('stage'));render();if(state.status!=='playing')showDialog('result');
